def chance(difficulte, bonus):
    reussites = 0
    for de_espoir in range(1, 13):
        for de_peur in range(1, 13):
            critique = de_espoir == de_peur
            if critique or de_espoir + de_peur + bonus >= difficulte:
                reussites += 1
    return round(100 * reussites / 144)


for difficulte in [10, 12, 15, 18, 20]:
    print("Difficulté", difficulte, ":", chance(difficulte, 1), "%")

compte = 0
for de_espoir in range(1, 13):
    for de_peur in range(1, 13):
        # Complète la condition
        if de_espoir + de_peur + 2 >= 15:
            compte += 1

print(compte, "sur 144, soit", round(100 * compte / 144), "%")

